#!/usr/bin/env python3
"""Move HeLx secrets between Helm values files and Vault-ready JSON files.

Under `make helm-deploy`, a chart builds each Kubernetes Secret from Helm
values, typically a hand-kept secrets.yaml. Under Argo CD, External Secrets
builds it from a Vault entry instead, copying the entry's keys as they are. The
two hold the same information in different shapes; deploy/helm/vault-secrets.yaml
records how one maps onto the other, and the commands here convert:

  to-vault      Render the umbrella chart with the given values files and write
                each Secret it would create as <out>/<service>/<secret>.json.
                It renders twice and refuses to write anything if a key differs
                between the two, because that value is generated by the chart
                and would change on every Argo CD sync.
  to-helm       Read those JSON files and write the single secrets.yaml that
                makes the charts create the same Secrets.
  from-cluster  Copy the live Secrets of a running release into the same JSON
                files.
  upload        Write those JSON files to Vault with `vault kv put`, one entry
                per file, after showing them and asking.

Every file written holds plaintext secrets, so files are created readable by
their owner only. Only `upload` talks to Vault, and nothing here writes to Git.
"""

from __future__ import annotations

import argparse
import base64
import binascii
import json
import os
import shutil
import subprocess
import sys
from collections.abc import Callable, Iterable, Sequence
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

import yaml

ROOT = Path(__file__).resolve().parents[2]
MAP_FILE = Path("deploy/helm/vault-secrets.yaml")
DEFAULT_VAULT_MOUNT = "helx"

ValuesPath = tuple[str, ...]


class SecretsError(Exception):
    """A problem the user has to fix; printed without a traceback."""


def split_path(text: str, where: str) -> ValuesPath:
    """Split a dotted values path such as appstore.secret.values."""
    if not isinstance(text, str) or not text.strip():
        raise SecretsError(f"{where}: a values path must be a non-empty string")
    parts = tuple(text.strip().split("."))
    if any(not part for part in parts):
        raise SecretsError(f"{where}: {text!r} has an empty segment")
    return parts


@dataclass(frozen=True)
class SecretSpec:
    """One entry of deploy/helm/vault-secrets.yaml."""

    name_template: str
    service: str
    values: ValuesPath | None = None
    keys: dict[str, ValuesPath] = field(default_factory=dict)
    derived: frozenset[str] = frozenset()
    set_values: dict[ValuesPath, Any] = field(default_factory=dict)
    encoded: dict[ValuesPath, str] = field(default_factory=dict)

    def name(self, release: str) -> str:
        return self.name_template.replace("{release}", release)

    def values_path(self, key: str) -> ValuesPath | None:
        """Where `key` lives in the Helm values; None for a derived key."""
        if key in self.derived:
            return None
        if self.values is not None:
            # The key is one segment even when it contains dots, e.g. tls.crt.
            return (*self.values, key)
        if key in self.keys:
            return self.keys[key]
        raise SecretsError(
            f"key {key!r} of Secret {self.name_template} has no place in the Helm "
            f"values; add it to `keys` or `derived` in {MAP_FILE}"
        )


def load_map(path: Path) -> list[SecretSpec]:
    """Read and check deploy/helm/vault-secrets.yaml."""
    try:
        data = yaml.safe_load(path.read_text(encoding="utf-8"))
    except FileNotFoundError:
        raise SecretsError(f"{path} does not exist") from None
    entries = data.get("secrets") if isinstance(data, dict) else None
    if not isinstance(entries, list) or not entries:
        raise SecretsError(f"{path}: expected a non-empty `secrets` list")
    specs: list[SecretSpec] = []
    seen: set[str] = set()
    for index, entry in enumerate(entries):
        where = f"{path}: secrets[{index}]"
        if not isinstance(entry, dict):
            raise SecretsError(f"{where}: expected a mapping")
        unknown = set(entry) - {"name", "service", "values", "keys", "derived", "set", "encoded"}
        if unknown:
            raise SecretsError(f"{where}: unknown fields {sorted(unknown)}")
        name = entry.get("name")
        service = entry.get("service")
        if not isinstance(name, str) or not name:
            raise SecretsError(f"{where}: `name` is required")
        if not isinstance(service, str) or not service or "/" in service:
            raise SecretsError(f"{where}: `service` must be a single folder name")
        if name in seen:
            raise SecretsError(f"{where}: {name} is listed twice")
        seen.add(name)
        has_values = "values" in entry
        has_keys = "keys" in entry
        if has_values == has_keys:
            raise SecretsError(f"{where}: set exactly one of `values` or `keys`")
        keys = entry.get("keys") or {}
        if not isinstance(keys, dict):
            raise SecretsError(f"{where}: `keys` must map key names to values paths")
        derived = entry.get("derived") or []
        set_values = entry.get("set") or {}
        encoded = entry.get("encoded") or {}
        if not isinstance(derived, list) or not all(isinstance(k, str) for k in derived):
            raise SecretsError(f"{where}: `derived` must be a list of key names")
        if not isinstance(set_values, dict) or not isinstance(encoded, dict):
            raise SecretsError(f"{where}: `set` and `encoded` must be mappings")
        specs.append(
            SecretSpec(
                name_template=name,
                service=service,
                values=split_path(entry["values"], f"{where}.values") if has_values else None,
                keys={str(k): split_path(v, f"{where}.keys.{k}") for k, v in keys.items()},
                derived=frozenset(derived),
                set_values={split_path(k, f"{where}.set"): v for k, v in set_values.items()},
                encoded={split_path(k, f"{where}.encoded"): str(v) for k, v in encoded.items()},
            )
        )
    return specs


# --- choosing values files -------------------------------------------------


def expand_entry(entry: str, root: Path, home: Path) -> Path:
    """Resolve one line of LOCAL_VALUES_FILE the way helm-deploy does."""
    if entry == "~":
        return home
    if entry.startswith("~/"):
        return home / entry[2:]
    path = Path(entry)
    return path if path.is_absolute() else root / path


def read_values_list(list_file: Path, root: Path, home: Path) -> tuple[list[Path], list[str]]:
    """Return the existing files LOCAL_VALUES_FILE names, and warnings for the rest."""
    files: list[Path] = []
    warnings: list[str] = []
    for number, raw in enumerate(list_file.read_text(encoding="utf-8").splitlines(), start=1):
        entry = raw.strip()
        if not entry or entry.startswith("#"):
            continue
        path = expand_entry(entry, root, home)
        if path.is_file():
            files.append(path)
        else:
            warnings.append(f"{list_file} line {number} names {entry}, which does not exist")
    if not files and not warnings:
        warnings.append(f"{list_file} names no values files")
    return files, warnings


def choose_values_files(
    list_file: Path,
    extra: Sequence[str],
    *,
    root: Path,
    home: Path,
    assume_yes: bool,
    confirm: Callable[[str], bool],
    report: Callable[[str], None],
) -> list[Path]:
    """Decide which values files to render with.

    LOCAL_VALUES_FILE's entries come first and VALUES after them, as in
    helm-deploy, and using the list file always needs a yes. Without the list
    file, VALUES alone is used as given; with neither, there is nothing to do.
    """
    extra_paths = [expand_entry(entry, root, home) for entry in extra]
    missing_extra = [str(path) for path in extra_paths if not path.is_file()]
    if missing_extra:
        raise SecretsError("VALUES names files that do not exist: " + ", ".join(missing_extra))

    if not list_file.is_file():
        if not extra_paths:
            raise SecretsError(
                f"No values files to render with: {list_file} does not exist and VALUES is "
                "empty.\nEither create that file, with one values-file path per line, or "
                'pass the files directly: VALUES="a.yaml b.yaml".'
            )
        report(f"{list_file} does not exist; using VALUES only.")
        return extra_paths

    files, warnings = read_values_list(list_file, root, home)
    chosen = files + extra_paths
    report(f"Values files from {list_file}" + (" and VALUES" if extra_paths else "") + ":")
    for path in chosen:
        report(f"  {path}")
    for warning in warnings:
        report(f"WARNING: {warning}; its values will not be used.")
    if not chosen:
        raise SecretsError("No values files to render with.")
    if assume_yes:
        report("ASSUME_YES is set; continuing without asking.")
        return chosen
    if not confirm("Render with these values files? [y/N] "):
        raise SecretsError("Cancelled; nothing was written.")
    return chosen


def confirm_on_tty(prompt: str, tty_path: str = "/dev/tty") -> bool:
    """Ask on the terminal, even when stdin and stdout are redirected.

    The terminal is opened once for writing and once for reading: Python cannot
    open it for both in one text file, because a terminal is not seekable.
    """
    try:
        with open(tty_path, "w", encoding="utf-8") as output, open(tty_path, encoding="utf-8") as answer:
            output.write(prompt)
            output.flush()
            reply = answer.readline().strip()
    except OSError:
        raise SecretsError(
            "No terminal to ask on, so cancelling rather than assuming yes.\n"
            "Set ASSUME_YES=1 to continue without the prompt."
        ) from None
    return reply in ("y", "Y")


# --- reading Secrets -------------------------------------------------------


def secret_data(secret: dict[str, Any], where: str) -> dict[str, str]:
    """Decode a Secret object's data and stringData into plain strings."""
    decoded: dict[str, str] = {}
    for key, value in (secret.get("data") or {}).items():
        try:
            decoded[key] = base64.b64decode(str(value), validate=True).decode("utf-8")
        except (binascii.Error, UnicodeDecodeError):
            raise SecretsError(f"{where}: key {key!r} is not base64-encoded UTF-8 text") from None
    for key, value in (secret.get("stringData") or {}).items():
        decoded[key] = str(value)
    return decoded


def rendered_secrets(manifest: str) -> dict[str, dict[str, str]]:
    """Every Secret in a rendered manifest, by name."""
    secrets: dict[str, dict[str, str]] = {}
    for document in yaml.safe_load_all(manifest):
        if isinstance(document, dict) and document.get("kind") == "Secret":
            name = (document.get("metadata") or {}).get("name", "")
            secrets[name] = secret_data(document, f"rendered Secret {name}")
    return secrets


def generated_keys(
    first: dict[str, dict[str, str]],
    second: dict[str, dict[str, str]],
    specs: Iterable[SecretSpec],
    release: str,
) -> list[str]:
    """Describe, per Secret, the values to set for keys that differ between renders."""
    problems: list[str] = []
    for spec in specs:
        name = spec.name(release)
        if name not in first:
            continue
        a, b = first[name], second.get(name, {})
        paths: list[str] = []
        for key in sorted(set(a) | set(b)):
            if key in spec.derived or a.get(key) == b.get(key):
                continue
            path = spec.values_path(key)
            assert path is not None
            paths.append(".".join(path))
        if not paths:
            continue
        paths += [f"{'.'.join(p)}: {v}" for p, v in spec.set_values.items()]
        paths += [f"{'.'.join(p)} (the base64 of {k})" for p, k in spec.encoded.items()]
        problems.append(f"  {name}:\n" + "\n".join(f"    {p}" for p in paths))
    return problems


# --- writing files ---------------------------------------------------------


def make_private_dir(path: Path) -> None:
    path.mkdir(parents=True, exist_ok=True)
    path.chmod(0o700)


def write_private(path: Path, text: str) -> None:
    """Write a file readable by its owner only, from the moment it exists."""
    make_private_dir(path.parent)
    descriptor = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
    with os.fdopen(descriptor, "w", encoding="utf-8") as handle:
        handle.write(text)
    path.chmod(0o600)


def secret_json(data: dict[str, str]) -> str:
    return json.dumps(data, indent=2, sort_keys=True, ensure_ascii=False) + "\n"


def json_path(out: Path, spec: SecretSpec, release: str) -> Path:
    return out / spec.service / f"{spec.name(release)}.json"


VAULT_PATH_MEANING = (
    "VAULT_PATH is the path prefix, on the {mount} mount, under which all of this "
    "namespace's secrets are stored, e.g. dev/azure/ai-sb-test."
)


def entry_path(vault_path: str, spec: SecretSpec, release: str) -> str:
    """The Vault entry, below the mount, that holds one Secret."""
    return f"{vault_path.strip('/')}/{spec.service}/{spec.name(release)}"


def upload_command(mount: str, vault_path: str, spec: SecretSpec, release: str, file: Path) -> str:
    """One `vault kv put`; with no VAULT_PATH given, it reads $VAULT_PATH from the shell."""
    prefix = vault_path.strip("/") or "$VAULT_PATH"
    return f"vault kv put -mount={mount} {prefix}/{spec.service}/{spec.name(release)} @{file}"


def write_secret_files(
    secrets: dict[str, dict[str, str]],
    specs: Sequence[SecretSpec],
    *,
    release: str,
    out: Path,
    mount: str,
    vault_path: str,
    report: Callable[[str], None],
) -> list[Path]:
    """Write one JSON file per mapped Secret present, and print upload commands."""
    written: list[Path] = []
    commands: list[str] = []
    make_private_dir(out)
    for spec in specs:
        name = spec.name(release)
        if name not in secrets:
            report(f"Skipped {name}: not found.")
            continue
        file = json_path(out, spec, release)
        write_private(file, secret_json(secrets[name]))
        written.append(file)
        commands.append(upload_command(mount, vault_path, spec, release, file))
    if not written:
        raise SecretsError("None of the Secrets in the map were found; nothing was written.")
    report(f"Wrote {len(written)} files under {out}.")
    prefix = vault_path.strip("/")
    report(
        "Upload them all with `make vault-secrets-upload VAULT_PATH="
        + (prefix or "<prefix>")
        + "`, or one at a time from a machine logged in to Vault:"
    )
    if not prefix:
        report("  " + VAULT_PATH_MEANING.format(mount=mount) + " Set it first:")
        report("  export VAULT_PATH=dev/azure/ai-sb-test")
    for command in commands:
        report(f"  {command}")
    report("Delete the files once they are uploaded.")
    return written


# --- to-helm ---------------------------------------------------------------


def set_path(tree: dict[str, Any], path: ValuesPath, value: Any, where: str) -> None:
    node = tree
    for part in path[:-1]:
        child = node.setdefault(part, {})
        if not isinstance(child, dict):
            raise SecretsError(f"{where}: {'.'.join(path)} conflicts with a value at {part}")
        node = child
    if path[-1] in node and node[path[-1]] != value:
        raise SecretsError(f"{where}: {'.'.join(path)} would be set to two different values")
    node[path[-1]] = value


def helm_values(
    secrets: dict[str, dict[str, str]], specs: Sequence[SecretSpec], release: str
) -> dict[str, Any]:
    """The Helm values that make the charts create exactly these Secrets."""
    tree: dict[str, Any] = {}
    for spec in specs:
        name = spec.name(release)
        if name not in secrets:
            continue
        data = secrets[name]
        for key in sorted(data):
            path = spec.values_path(key)
            if path is not None:
                set_path(tree, path, data[key], name)
        for path, value in spec.set_values.items():
            set_path(tree, path, value, name)
        for path, key in spec.encoded.items():
            if key not in data:
                raise SecretsError(f"{name} has no key {key!r}, needed for {'.'.join(path)}")
            encoded = base64.b64encode(data[key].encode("utf-8")).decode("ascii")
            set_path(tree, path, encoded, name)
    return tree


class LiteralDumper(yaml.SafeDumper):
    """Write multi-line strings, such as certificates, as readable blocks."""


def _represent_str(dumper: yaml.SafeDumper, value: str) -> yaml.ScalarNode:
    style = "|" if "\n" in value else None
    return dumper.represent_scalar("tag:yaml.org,2002:str", value, style=style)


LiteralDumper.add_representer(str, _represent_str)


def helm_values_yaml(tree: dict[str, Any], source: str) -> str:
    header = (
        f"# Generated by `make vault-secrets-to-helm` from {source}.\n"
        "# Plaintext secrets: keep this file out of Git and readable by you only.\n"
    )
    return header + yaml.dump(tree, Dumper=LiteralDumper, sort_keys=False, default_flow_style=False)


def read_secret_files(
    directory: Path, specs: Sequence[SecretSpec], release: str, report: Callable[[str], None]
) -> dict[str, dict[str, str]]:
    secrets: dict[str, dict[str, str]] = {}
    for spec in specs:
        file = json_path(directory, spec, release)
        if not file.is_file():
            report(f"Skipped {spec.name(release)}: {file} does not exist.")
            continue
        try:
            data = json.loads(file.read_text(encoding="utf-8"))
        except json.JSONDecodeError as error:
            raise SecretsError(f"{file}: not valid JSON ({error})") from None
        if not isinstance(data, dict) or not all(isinstance(v, str) for v in data.values()):
            raise SecretsError(f"{file}: expected a JSON object of string values")
        secrets[spec.name(release)] = data
    if not secrets:
        raise SecretsError(f"No Secret files from the map were found under {directory}.")
    return secrets


# --- commands ---------------------------------------------------------------


def run(command: Sequence[str]) -> str:
    result = subprocess.run(list(command), capture_output=True, text=True)
    if result.returncode != 0:
        raise SecretsError(f"{command[0]} failed:\n{result.stderr.strip()}")
    return result.stdout


def helm_template(chart: str, release: str, namespace: str, values: Sequence[Path]) -> str:
    command = ["helm", "template", release, chart]
    if namespace:
        command += ["--namespace", namespace]
    for path in values:
        command += ["--values", str(path)]
    return run(command)


def vault_put(mount: str, path: str, file: Path) -> None:
    """Write one Vault KV entry from a JSON file. Its output names no values."""
    run(["vault", "kv", "put", f"-mount={mount}", path, f"@{file}"])


def kubectl_secret(name: str, namespace: str, context: str) -> dict[str, Any] | None:
    command = ["kubectl"]
    if context:
        command += ["--context", context]
    if namespace:
        command += ["--namespace", namespace]
    command += ["get", "secret", name, "--output", "json", "--ignore-not-found"]
    output = run(command).strip()
    return json.loads(output) if output else None


def command_to_vault(args: argparse.Namespace, specs: Sequence[SecretSpec], report) -> None:
    values = choose_values_files(
        Path(args.values_list) if Path(args.values_list).is_absolute() else ROOT / args.values_list,
        args.values,
        root=ROOT,
        home=Path.home(),
        assume_yes=args.assume_yes,
        confirm=confirm_on_tty,
        report=report,
    )
    report(f"Rendering {args.chart} twice as release {args.release}.")
    first = rendered_secrets(helm_template(args.chart, args.release, args.namespace, values))
    second = rendered_secrets(helm_template(args.chart, args.release, args.namespace, values))
    problems = generated_keys(first, second, specs, args.release)
    if problems:
        raise SecretsError(
            "These values are generated by the chart, so they change on every render "
            "and would change on every Argo CD sync. Add them to your secrets.yaml "
            "(for a running release, take them from `make vault-secrets-from-cluster` "
            "and `make vault-secrets-to-helm`):\n" + "\n".join(problems)
        )
    write_secret_files(
        first,
        specs,
        release=args.release,
        out=Path(args.out),
        mount=args.vault_mount,
        vault_path=args.vault_path,
        report=report,
    )


def command_to_helm(args: argparse.Namespace, specs: Sequence[SecretSpec], report) -> None:
    secrets = read_secret_files(Path(args.input), specs, args.release, report)
    out = Path(args.out_file)
    write_private(out, helm_values_yaml(helm_values(secrets, specs, args.release), args.input))
    report(f"Wrote {out} from {len(secrets)} Secrets.")
    report(f"Use it with: make helm-deploy VALUES={out}")


def confirm_overwrite(
    files: Sequence[Path],
    *,
    assume_yes: bool,
    confirm: Callable[[str], bool],
    report: Callable[[str], None],
) -> None:
    """Ask before replacing files that already exist; ask nothing if none do."""
    existing = [file for file in files if file.exists()]
    if not existing:
        return
    report("These files already exist and would be overwritten:")
    for file in existing:
        report(f"  {file}")
    if assume_yes:
        report("ASSUME_YES is set; overwriting without asking.")
        return
    if not confirm("Overwrite them? [y/N] "):
        raise SecretsError("Cancelled; no files were changed.")


def command_from_cluster(args: argparse.Namespace, specs: Sequence[SecretSpec], report) -> None:
    secrets: dict[str, dict[str, str]] = {}
    for spec in specs:
        name = spec.name(args.release)
        secret = kubectl_secret(name, args.namespace, args.context)
        if secret is not None:
            secrets[name] = secret_data(secret, f"Secret {name}")
    confirm_overwrite(
        [json_path(Path(args.out), spec, args.release) for spec in specs if spec.name(args.release) in secrets],
        assume_yes=args.assume_yes,
        confirm=confirm_on_tty,
        report=report,
    )
    write_secret_files(
        secrets,
        specs,
        release=args.release,
        out=Path(args.out),
        mount=args.vault_mount,
        vault_path=args.vault_path,
        report=report,
    )


def command_upload(args: argparse.Namespace, specs: Sequence[SecretSpec], report) -> None:
    prefix = args.vault_path.strip("/")
    if not prefix:
        raise SecretsError(
            "VAULT_PATH is not set. " + VAULT_PATH_MEANING.format(mount=args.vault_mount)
            + "\nFor example: make vault-secrets-upload VAULT_PATH=dev/azure/ai-sb-test"
        )
    address = os.environ.get("VAULT_ADDR", "")
    if not address:
        raise SecretsError(
            "VAULT_ADDR is not set, so the vault command would not know which Vault to use.\n"
            "Set it and log in first, e.g.:\n"
            "  export VAULT_ADDR=https://vault.apps.renci.org\n"
            "  vault login"
        )
    if shutil.which("vault") is None:
        raise SecretsError("The vault command is not installed or not on PATH.")

    directory = Path(args.input)
    entries: list[tuple[SecretSpec, Path]] = []
    for spec in specs:
        file = json_path(directory, spec, args.release)
        if file.is_file():
            entries.append((spec, file))
        else:
            report(f"Skipped {spec.name(args.release)}: {file} does not exist.")
    if not entries:
        raise SecretsError(f"No Secret files from the map were found under {directory}.")

    report(f"Vault: {address}")
    report(f"Entries to write on the {args.vault_mount} mount (each becomes a new version):")
    for spec, file in entries:
        report(f"  {entry_path(prefix, spec, args.release)}  <-  {file}")
    if args.assume_yes:
        report("ASSUME_YES is set; continuing without asking.")
    elif not confirm_on_tty(f"Write these {len(entries)} entries to Vault? [y/N] "):
        raise SecretsError("Cancelled; nothing was written to Vault.")

    done: list[str] = []
    for spec, file in entries:
        path = entry_path(prefix, spec, args.release)
        try:
            vault_put(args.vault_mount, path, file)
        except SecretsError as error:
            not_done = [entry_path(prefix, s, args.release) for s, _ in entries[len(done):]]
            raise SecretsError(
                f"Writing {path} failed, so the rest were not attempted.\n"
                f"Written: {', '.join(done) or 'none'}\n"
                f"Not written: {', '.join(not_done)}\n{error}"
            ) from None
        done.append(path)
        report(f"Wrote {args.vault_mount}/{path}")
    report(f"Wrote {len(done)} entries. Delete the files under {directory} once you no longer need them.")


def parse_args(argv: Sequence[str] | None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--map", default=str(MAP_FILE), help="the Secret map (default: %(default)s)")
    parser.add_argument("--release", default="helx", help="Helm release name (default: %(default)s)")
    commands = parser.add_subparsers(dest="command", required=True)

    def add_output(sub: argparse.ArgumentParser) -> None:
        sub.add_argument("--out", required=True, help="directory for the JSON files")
        sub.add_argument("--vault-mount", default=DEFAULT_VAULT_MOUNT)
        sub.add_argument("--vault-path", default="", help="e.g. dev/azure/ai-sb-test")

    to_vault = commands.add_parser("to-vault", help="values files -> JSON per Secret")
    to_vault.add_argument("--chart", required=True, help="packaged umbrella chart or chart directory")
    to_vault.add_argument("--namespace", default="")
    to_vault.add_argument("--values-list", required=True, help="LOCAL_VALUES_FILE")
    to_vault.add_argument("--values", nargs="*", default=[], help="VALUES files")
    to_vault.add_argument("--assume-yes", action="store_true")
    add_output(to_vault)

    to_helm = commands.add_parser("to-helm", help="JSON per Secret -> one secrets.yaml")
    to_helm.add_argument("--in", dest="input", required=True, help="directory of JSON files")
    to_helm.add_argument("--out-file", required=True, help="secrets.yaml to write")

    from_cluster = commands.add_parser("from-cluster", help="live Secrets -> JSON per Secret")
    from_cluster.add_argument("--namespace", default="")
    from_cluster.add_argument("--context", default="")
    from_cluster.add_argument("--assume-yes", action="store_true", help="overwrite without asking")
    add_output(from_cluster)

    upload = commands.add_parser("upload", help="JSON per Secret -> Vault entries")
    upload.add_argument("--in", dest="input", required=True, help="directory of JSON files")
    upload.add_argument("--vault-mount", default=DEFAULT_VAULT_MOUNT)
    upload.add_argument("--vault-path", default="", help="e.g. dev/azure/ai-sb-test")
    upload.add_argument("--assume-yes", action="store_true")
    return parser.parse_args(argv)


def main(argv: Sequence[str] | None = None) -> int:
    args = parse_args(argv)
    map_path = Path(args.map)
    specs = load_map(map_path if map_path.is_absolute() else ROOT / map_path)

    def report(message: str) -> None:
        print(message, file=sys.stderr)

    handlers = {
        "to-vault": command_to_vault,
        "to-helm": command_to_helm,
        "from-cluster": command_from_cluster,
        "upload": command_upload,
    }
    try:
        handlers[args.command](args, specs, report)
    except SecretsError as error:
        report(f"ERROR: {error}")
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
